import * as React from 'react';
import { useState } from 'react';
import Button from '@mui/material/Button';
import ButtonGroup from '@mui/material/ButtonGroup';
import Box from '@mui/material/Box';
import Stack from '@mui/material/Stack';
import Typography from '@mui/material/Typography';
import { createTheme, ThemeProvider } from '@mui/material/styles';
import Paper from '@mui/material/Paper';

const darkTheme = createTheme({
  palette: {
    mode: 'dark',
    primary: {
      main: '#90caf9',
    },
    background: {
      default: '#121212',
      paper: '#1e1e1e',
    },
  },
});

export default function DarkThemeCalculator() {
  const [expression, setExpression] = useState('');
  const [result, setResult] = useState('');

  const handleButtonClick = (value) => {
    if (value === '=') {
      try {
        // Evaluate the expression
        const evalResult = eval(expression);
        setResult(evalResult);
      } catch {
        setResult('Error');
      }
    } else if (value === 'C') {
      setExpression('');
      setResult('');
    } else {
      setExpression((prev) => prev + value);
    }
  };

  return (
    <ThemeProvider theme={darkTheme}>
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          height: '100vh',
          bgcolor: 'background.default',
          color: 'text.primary',
          p: 2,
        }}
      >
        <Paper elevation={3} sx={{ width: 300, p: 2 }}>
          <Typography variant="h5" gutterBottom textAlign="center">
            Calculator
          </Typography>
          <Typography variant="body1" textAlign="right" sx={{ minHeight: '1.5em' }}>
            {expression}
          </Typography>
          <Typography variant="h6" textAlign="right" sx={{ minHeight: '1.5em', mb: 2 }}>
            {result}
          </Typography>
          {[['1', '2', '3'], ['4', '5', '6'], ['7', '8', '9']].map((row, index) => (
            <ButtonGroup key={index} variant="text" fullWidth sx={{ mb: 1 }}>
              {row.map((num) => (
                <Button key={num} onClick={() => handleButtonClick(num)}>{num}</Button>
              ))}
            </ButtonGroup>
          ))}
          <Stack direction="row" spacing={1} justifyContent="center" mb={1}>
            {['/', '*', '-', '+', '='].map((op) => (
              <Button
                key={op}
                variant="contained"
                color="primary"
                onClick={() => handleButtonClick(op)}
              >
                {op}
              </Button>
            ))}
          </Stack>
          <Button
            variant="outlined"
            color="error"
            fullWidth
            onClick={() => handleButtonClick('C')}
          >
            Clear
          </Button>
        </Paper>
      </Box>
    </ThemeProvider>
  );
}